          [3, 2]]   # Rate_{P2,S1}, Rate_{P2,S2}
profit = [10, 20]   # Profit_{P1}, Profit_{P2}
commit = [1, 2]     # Commit_{P1}, Commit_{P2}
market = [5, 4]     # Market_{P1}, Market_{P2}
avail  = [10, 8]    # Available_{S1}, Available_{S2}

# Create model with the runtime-provided environment
model = gp.Model(env=env)

# Decision variables with bounds
lb = {p: commit[i] for i, p in enumerate(products)}
ub = {p: market[i] for i, p in enumerate(products)}
x  = model.addVars(products, lb=lb, ub=ub, vtype=GRB.CONTINUOUS, name='x')

# Objective: maximize total profit
model.setObjective(gp.quicksum(profit[i] * x[p] for i, p in enumerate(products)), GRB.MAXIMIZE)

# Stage capacity constraints
for s_idx, s in enumerate(stages):
    model.addConstr(
        gp.quicksum(rate[p_idx][s_idx] * x[p] for p_idx, p in enumerate(products)) <= avail[s_idx],
        name=f'Cap_{s}'
    )

# Optimize
model.optimize()

# Print the optimal objective value
print(f"FINAL_OBJECTIVE={model.ObjVal}")
